mapper.select:
SELECT 
FROM activity_record r
JOIN team t ON t.team_id = r.team_id
JOIN member creator ON creator.member_id = r.created_by_member_id
WHERE r.deleted_dttm IS NULL
  AND r.status_code = 'APPROVED'

  AND r.team_id = #{teamId}


  AND r.activity_dttm >= #{rangeStart}


  AND r.activity_dttm < #{rangeEnd}

ORDER BY r.activity_dttm DESC, r.activity_record_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM activity_record r
JOIN team t ON t.team_id = r.team_id
JOIN member creator ON creator.member_id = r.created_by_member_id
WHERE r.deleted_dttm IS NULL

  AND r.team_id = #{teamId}


  AND r.status_code = #{status}


  AND r.created_by_member_id = #{createdByMemberId}

ORDER BY r.updated_dttm DESC, r.activity_record_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS(
    SELECT 1
    FROM activity_record_file
    WHERE activity_record_id = #{activityRecordId}
      AND stored_file_id = #{storedFileId}
      AND replaced_dttm IS NULL
)

SELECT COALESCE(MAX(display_order) + 1, 0)
FROM activity_record_file
WHERE activity_record_id = #{activityRecordId}
  AND file_role_code = #{fileRole}
  AND replaced_dttm IS NULL

SELECT COUNT(*)
FROM activity_record_file
WHERE activity_record_id = #{activityRecordId}
  AND file_role_code = #{fileRole}
  AND replaced_dttm IS NULL

mapper.insert:
INSERT INTO activity_record (
    team_id, activity_dttm, title, body, participant_count,
    status_code, created_by_member_id, updated_by_member_id,
    submitted_dttm, reviewed_dttm, reviewed_by_member_id
) VALUES (
    #{teamId}, #{activityDttm}, #{title}, #{body}, #{participantCount},
    #{status}, #{createdByMemberId}, #{updatedByMemberId},
    #{submittedDttm}, #{reviewedDttm}, #{reviewedByMemberId}
)

INSERT INTO activity_record_file (
    activity_record_id, stored_file_id, file_role_code,
    display_order, uploaded_by_member_id
) VALUES (
    #{activityRecordId}, #{storedFileId}, #{fileRole},
    #{displayOrder}, #{uploadedByMemberId}
)

mapper.update:
UPDATE activity_record_file
SET replaced_by_activity_record_file_id = #{replacedByActivityRecordFileId},
    replaced_dttm = #{replacedDttm},
    replaced_by_member_id = #{replacedByMemberId}
WHERE activity_record_file_id = #{activityRecordFileId}
  AND replaced_dttm IS NULL

mapper.insert:
INSERT INTO activity_record_revision (
    activity_record_id, revision_no, activity_dttm, title, body,
    participant_count, changed_by_member_id, changed_dttm, change_reason
) VALUES (
    #{activityRecordId}, #{revisionNo}, #{activityDttm}, #{title}, #{body},
    #{participantCount}, #{changedByMemberId}, #{changedDttm}, #{changeReason}
)

INSERT INTO activity_review_history (
    activity_record_id, previous_status_code, new_status_code,
    comment, reviewed_by_member_id, reviewed_dttm
) VALUES (
    #{activityRecordId}, #{previousStatus}, #{newStatus},
    #{comment}, #{reviewedByMemberId}, #{reviewedDttm}
)
